<script setup lang="ts">
import FuturePanels from '../meetings/FuturePanels.vue';import MinutesTemplateToolbar from './MinutesTemplateToolbar.vue';import MinutesSensitive from './MinutesSensitive.vue';
import ActionOwnerSelection from './ActionOwnerSelection.vue';import type {Person} from '../../shared/api/meeting-options';
import MinutesGenerationPanel from './MinutesGenerationPanel.vue';
import MinutesSettings from './MinutesSettings.vue';import {captureEvidenceAnchors,reanchorEvidence} from './minutes-anchors';
import PublicationPanel from './PublicationPanel.vue';import {useEditorIntent} from '../../shared/composables/useEditorIntent';
import {computed,shallowRef,ref,watch,onUnmounted,nextTick} from 'vue';import {useApplication} from '../../application';import {useMinutesEditor} from './useMinutesEditor';import {useMinutesActions} from './useMinutesActions';import MinutesTextEditor from './MinutesTextEditor.vue';import MinutesHistory from './MinutesHistory.vue';import type {SavedMeeting} from '../../shared/api/meeting-info';
import type {components} from '../../shared/api/generated';
import type {MinutesCurrent,MinutesOperation} from '../../shared/api/minutes-saved';import type {Candidate,Candidates,Source} from '../../shared/api/minutes-inspection';import type {MinutesTarget} from './minutes-editor-journal';import {ApiError} from '../../shared/api/client';import {scalarOffset} from '../../shared/scalar-anchors';
const props=withDefaults(defineProps<{meetingId:string;owner:boolean;meetingInfo?:SavedMeeting;stage?:string;autoGenerate?:boolean;pendingCandidates?:{id:string}[]}>(),{stage:'minutes',pendingCandidates:()=>[]});const emit=defineEmits<{changed:[];editInfo:[];published:[];infoSaved:[];generationStarted:[];navigate:[stage:string]}>();const app=useApplication(),actor=()=>app.session.current.value?.actor.enterpriseId??null;
const futurePanels=ref<InstanceType<typeof FuturePanels>>(),copyMessage=ref(''),candidateDialog=ref<HTMLDialogElement>(),toolsDialog=ref<HTMLDialogElement>(),generateDialog=ref<HTMLDialogElement>(),inspectDialog=ref<HTMLDialogElement>(),editDialog=ref<HTMLDialogElement>();
function candidateBackdrop(event:MouseEvent){const dialog=candidateDialog.value;if(!dialog||event.target!==dialog)return;const bounds=dialog.getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom)dialog.close();}
const sensitiveRef=ref<InstanceType<typeof MinutesSensitive>>(),saveMessage=ref('');
const bodyEditing=ref(false),generationOpened=ref(false),regenerationAuto=ref(false);
async function openGeneration(){if(!await beforeLeave())return;generationOpened.value=true;void nextTick(()=>generateDialog.value?.showModal());}
function generationStarted(){regenerationAuto.value=false;emit('generationStarted');}
const view=ref<'body'|'elements'|'candidates'|'publication'>('elements'),dirtyDialog=ref<HTMLDialogElement>();let leaveDecision:((allowed:boolean)=>void)|null=null;
async function beforeLeave(){if(!workspaceDirty.value)return true;return new Promise<boolean>(resolve=>{leaveDecision=resolve;dirtyDialog.value?.showModal();});}
async function changeView(next:typeof view.value){if(next!==view.value&&await beforeLeave()){if(next!=='body')bodyEditing.value=false;view.value=next;}}
const workspaceDirty=computed(()=>!!editor.draft.value?.dirty.value||!!sensitiveRef.value?.dirty);
async function decideLeave(choice:'save'|'discard'|'stay'){if(choice==='save'){if(!await saveWorkspace())return;}if(choice==='discard'){try{if(editor.draft.value?.dirty.value)editor.discard();if(sensitiveRef.value?.dirty)sensitiveRef.value.discard();}catch(e){error.value=e instanceof Error?e.message:'草稿暂不可处理';return;}}dirtyDialog.value?.close();leaveDecision?.(choice!=='stay');leaveDecision=null;}
watch(()=>props.stage,stage=>{view.value=['confirm','publish'].includes(stage)?'publication':stage==='published'?'body':'elements';},{immediate:true});
const selectedCategory=ref('OVERVIEW');
function categoryView(category:string){selectedCategory.value=category;document.getElementById('minutes-category-'+category)?.scrollIntoView({block:'start',behavior:'smooth'});}
const categoryLabels:Record<string,string>={OVERVIEW:'会议概述',DISCUSSION:'关键内容',CONCLUSION:'会议结论',ACTION:'行动项',RISK:'风险与阻碍',OPEN_QUESTION:'待解决问题',DISAGREEMENT:'分歧'};
const accessDenied=ref(false);const allowed=()=>props.owner&&app.minutesScopeReady.value&&!accessDenied.value;const authorize=async(id:string,signal:AbortSignal)=>{const v=await app.workspace.navigation(id,signal);return v.relation==='OWNER'&&['CHECK_PRODUCER','PUBLISHED_READ_ONLY'].includes(v.navigationState);};
const editor=useMinutesEditor({...app.minutesSaved,authorize},actor,()=>props.meetingId,allowed,app.journals);const publicCurrent=shallowRef<MinutesCurrent|null>(null),error=ref(''),busy=ref(false),source=shallowRef<Source|null>(null),candidates=shallowRef<Candidates|null>(null),candidate=shallowRef<Candidate|null>(null),candidateState=ref<'PENDING'|'STALE'|'ADOPTED'|'REJECTED'>('PENDING');
const reviewHistory=shallowRef<components['schemas']['SavedReviewHistory']|null>(null),candidatePage=ref(0);
const selected=shallowRef<{kind:'BODY'|'ELEMENT';id:string}|null>(null),reviewOutcome=ref<'SUPPORTED'|'PARTIAL'|'UNSUPPORTED'>('SUPPORTED'),reviewSelection=ref<{startToken:string;endToken:string}|null>(null);const pages=ref<Record<string,number>>({});
let epoch=0,controller:AbortController|null=null;const value=computed(()=>props.owner?editor.current.value:publicCurrent.value);const locked=computed(()=>!allowed()||!!value.value?.observation.readOnlyReason||!value.value||editor.draft.value?.dirty.value||['PREPARED','SENDING','UNCERTAIN'].includes(editor.command.state.value));
watch(value,current=>{if(current)emit('changed');});
watch(()=>[props.autoGenerate,value.value?.body?.id],()=>{if(props.autoGenerate&&value.value?.body){regenerationAuto.value=true;openGeneration();}});
const selectedCandidateElements=computed(()=>candidate.value?.graph.minutes_element.filter(element=>element.set_id===candidate.value?.candidate.elementSetId)??[]);
const actionSession={},actionIntent=useEditorIntent(()=>allowed()&&actor()?{actor:actor()!,meetingId:props.meetingId,session:actionSession}:null,()=>!!locked.value,c=>app.minutesSaved.intent(c));
const actions=useMinutesActions({authorize:async(id,signal)=>{const v=await app.workspace.navigation(id,signal);return v.relation==='OWNER'&&v.navigationState==='CHECK_PRODUCER';},send:app.minutesSaved.send},actor,()=>props.meetingId,allowed,async()=>{await editor.reload();emit('changed');},app.journals);
const selectedContent=computed(()=>{const t=selected.value,v=value.value;if(!t||!v)return null;if(t.kind==='BODY')return v.body?.id===t.id?v.body:null;return Object.values(v.elements).flat().find(x=>x.id===t.id)??null;});
const displayGroups=computed(()=>{const e=value.value?.elements??{OVERVIEW:[],DISCUSSION:[],CONCLUSION:[],ACTION:[],OPEN_QUESTION:[],DISAGREEMENT:[],RISK:[]};return{OVERVIEW:e.OVERVIEW,DISCUSSION:e.DISCUSSION,CONCLUSION:e.CONCLUSION,ACTION:e.ACTION,OPEN_QUESTION:[...e.OPEN_QUESTION,...e.DISAGREEMENT],RISK:e.RISK};});
async function copyBody(){if(!value.value?.body||editor.draft.value?.dirty.value)return;try{await navigator.clipboard.writeText(value.value.body.title+'\n\n'+value.value.body.body);copyMessage.value='已复制全文';}catch{copyMessage.value='浏览器未允许复制，请选中文字复制。';}}
function downloadBody(){if(!value.value?.body||editor.draft.value?.dirty.value)return;const body=value.value.body,url=URL.createObjectURL(new Blob(['# '+body.title+'\n\n'+body.body],{type:'text/markdown;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=(body.title.replace(/[<>:"/\\|?*]/g,'_').slice(0,100)||'会议纪要')+'.md';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const reviewLabels=computed(()=>{const labels:Record<string,string>={};if(value.value?.body)labels[value.value.body.id]='纪要正文';for(const [category,items] of Object.entries(value.value?.elements??{}))for(const item of items)labels[item.id]=(categoryLabels[category]??category)+'：'+Array.from(item.body).slice(0,28).join('');return labels;});
function denied(cause:unknown){accessDenied.value=true;epoch++;controller?.abort();editor.deny(cause);actions.deny(cause);actionIntent.invalidate();reviewHistory.value=null;publicCurrent.value=null;source.value=null;candidates.value=null;candidateDialog.value?.close();candidate.value=null;selected.value=null;error.value=cause instanceof Error?cause.message:'访问权限已变化。';}
async function read<T>(fn:(signal:AbortSignal)=>Promise<T>,accept:(v:T)=>void){const turn=++epoch;controller?.abort();const request=new AbortController();controller=request;busy.value=true;error.value='';try{const v=await fn(request.signal);if(turn===epoch)accept(v);}catch(cause){if(turn===epoch){if(cause instanceof ApiError&&[401,403].includes(cause.status))denied(cause);else error.value=cause instanceof Error?cause.message:'读取失败。';}}finally{if(turn===epoch)busy.value=false;}}
async function reload(){inspectDialog.value?.close();actionIntent.invalidate();reviewHistory.value=null;accessDenied.value=false;source.value=null;selected.value=null;candidateDialog.value?.close();candidate.value=null;candidates.value=null;if(props.owner){await actions.reload();await editor.reload();}else await read(s=>app.minutesSaved.current(props.meetingId,s),v=>publicCurrent.value=v);}
function inspect(t:{kind:'BODY'|'ELEMENT';id:string;locatorId?:string}){if(editor.busy.value||editor.loading.value||actions.busy.value)return;const matches=(e:MinutesCurrent['evidence'][number])=>t.kind==='BODY'?e.minutes_revision_id===t.id:e.element_id===t.id;const evidence=value.value?.evidence.find(e=>matches(e)&&(!t.locatorId||e.locator_id===t.locatorId));if(t.locatorId&&!evidence){error.value='当前版本没有该目标与来源的关联，请重新核对。';return;}reviewHistory.value=null;actionIntent.invalidate();const target={kind:t.kind,id:t.id};selected.value=target;source.value=null;reviewSelection.value=null;void nextTick(()=>{if(inspectDialog.value&&!inspectDialog.value.open)inspectDialog.value.showModal();if(evidence)void read(s=>app.minutesInspection.source(props.meetingId,evidence.locator_id,target,s),v=>source.value=v);});}

async function edit(t:MinutesTarget){try{await editor.select(t);error.value='';await nextTick();inspectDialog.value?.close();if(t.kind==='BODY'){bodyEditing.value=true;await editor.begin();}else{bodyEditing.value=false;if(editDialog.value&&!editDialog.value.open)editDialog.value.showModal();}}catch(e){error.value=e instanceof Error?e.message:'编辑不可用。';}}
async function command(operation:MinutesOperation,fields:Record<string,unknown>,id?:string):Promise<string|null>{try{if(locked.value||operation!=='MINUTES_EXCLUSIONS'&&sensitiveRef.value?.dirty)throw new Error('请先保存草稿并重新读取当前纪要。');const revision=value.value!.observation.revisionToken,turn=epoch;actionIntent.invalidate();await actionIntent.request(revision);if(turn!==epoch||locked.value)return null;await actions.run(operation,{expectedRevisionToken:revision,...fields},id);if(operation==='MINUTES_ADOPT'&&actions.command.state.value==='ACKNOWLEDGED')view.value='body';source.value=null;selected.value=null;candidateDialog.value?.close();inspectDialog.value?.close();if(operation==='MINUTES_ADOPT')toolsDialog.value?.close();candidate.value=null;candidates.value=null;return actions.command.state.value==='ACKNOWLEDGED'&&!actions.error.value&&!editor.error.value?actions.command.ack.value?.resultId??null:null;}catch(e){error.value=e instanceof Error?e.message:'操作不可用。';return null;}}
function assignOwner(person:Person|null){
 const t=selected.value,current=value.value,content=selectedContent.value;
 if(!t||t.kind!=='ELEMENT'||!current?.setId||!content||!('action' in content)||!content.action)return;
 void command('MINUTES_ACTION_FIELDS',{sourceSetId:current.setId,ownerEnterpriseId:person?.stableId??null,ownerDisplay:person?.displayName??content.action.owner_display,dueOn:content.action.due_on},t.id);
}
function inspectCandidate(id:string){void read(s=>app.minutesInspection.candidate(props.meetingId,id,s),v=>{candidatePage.value=0;candidate.value=v;void nextTick(()=>{if(candidateDialog.value&&!candidateDialog.value.open)candidateDialog.value.showModal();});});}
function loadCandidates(next:string|null=null){candidateDialog.value?.close();candidate.value=null;void read(s=>app.minutesInspection.candidates(props.meetingId,candidateState.value,next,s),v=>candidates.value=v);}
function review(span=false){if(!selected.value||!selectedContent.value||span&&!reviewSelection.value)return;void command('MINUTES_REVIEW',{target:{kind:selected.value.kind,id:selected.value.id},reviewKind:'SOURCE_SUPPORT',scope:span?'SPAN':'WHOLE',outcome:reviewOutcome.value,...(span?reviewSelection.value:{})});}
function range(event:Event){const e=event.target as HTMLTextAreaElement;reviewSelection.value=e.selectionEnd>e.selectionStart?{startToken:scalarOffset(e.value,e.selectionStart),endToken:scalarOffset(e.value,e.selectionEnd)}:null;}
async function convertQuestion(){const t=selected.value,v=value.value,c=selectedContent.value;if(!t||t.kind!=='ELEMENT'||!v?.setId||!c)return;try{const anchor=await captureEvidenceAnchors(c.body,v.evidence.filter(e=>e.element_id===t.id));await command('MINUTES_OPEN_QUESTION',{sourceSetId:v.setId,body:c.body,evidenceAnchors:reanchorEvidence(c.body,anchor)},t.id);}catch(e){error.value=e instanceof Error?e.message:'来源位置暂不可确认。';}}
function loadReviews(next:string|null=null){const t=selected.value;if(t)void read(s=>app.minutesInspection.reviews(props.meetingId,t,next,s),v=>reviewHistory.value=v);}
const stopErrors=watch(()=>[editor.error.value,actions.error.value],values=>{const failure=values.find(x=>x instanceof ApiError&&[401,403].includes(x.status));if(failure&&!accessDenied.value)denied(failure);},{flush:'sync'});
const stop=watch(()=>[actor(),props.meetingId,props.owner,app.minutesScopeReady.value],()=>{epoch++;controller?.abort();publicCurrent.value=null;source.value=null;candidates.value=null;candidateDialog.value?.close();candidate.value=null;selected.value=null;error.value='';pages.value={};if(actor())void reload();},{immediate:true,flush:'sync'});
async function finishBodyEdit(){if(editor.draft.value?.dirty.value)await editor.save();if(!editor.error.value&&!editor.draft.value?.dirty.value)bodyEditing.value=false;}
async function keepCurrentCandidate(){const c=candidate.value?.candidate;if(!c||workspaceDirty.value||locked.value||actions.busy.value||!['PENDING','STALE'].includes(c.state))return;await command(c.state==='PENDING'?'MINUTES_REJECT':'MINUTES_DISPOSE',{},c.candidateId);}
async function saveWorkspace(){saveMessage.value='';if(editor.draft.value?.dirty.value){await editor.save();if(editor.error.value||editor.draft.value?.dirty.value)return false;}if(sensitiveRef.value?.dirty&&!await sensitiveRef.value.save())return false;saveMessage.value='没有未保存的修改';return !workspaceDirty.value;}
defineExpose({saveMessage,reload,openVersions:()=>toolsDialog.value?.showModal(),save:saveWorkspace,beforeLeave,dirty:workspaceDirty});
onUnmounted(()=>{stopErrors();stop();epoch++;controller?.abort();editor.dispose();actions.dispose();actionIntent.invalidate();});
</script>
<template><section class="minutes" :class="{'am-workbench':stage==='minutes','m19-published-minutes':stage==='published'}"><div v-show="stage==='minutes'" class="am-header-group"><nav class="tabs minutes-views" aria-label="纪要内容"><button class="tab" :class="{active:view==='elements'}" :aria-pressed="view==='elements'" @click="changeView('elements')">核心要素</button><button class="tab" :class="{active:view==='body'}" :aria-pressed="view==='body'" @click="changeView('body')">会议纪要</button></nav></div><div v-if="owner&&stage==='minutes'&&pendingCandidates.length" class="banner info candidate-banner"><span>新生成的纪要候选待核对，当前稿件保持不变。</span><button class="btn sm" @click="toolsDialog?.showModal();inspectCandidate(pendingCandidates[0]!.id)">核对纪要候选</button></div><p v-if="error" role="alert">{{error}}</p><p v-if="owner&&!app.minutesScopeReady.value" role="alert">恢复记录暂不可用，请使用页面上方的恢复检查。</p>
 <MinutesGenerationPanel v-if="stage==='minutes'&&owner&&value&&!value.body" :meeting-id="meetingId" :auto-start="autoGenerate" @started="generationStarted" @changed="reload();emit('changed')"/>
 <dialog ref="generateDialog" class="workspace-dialog" aria-label="重新生成纪要"><header class="between"><h3>重新生成纪要</h3><button class="btn sm" @click="generateDialog?.close()">关闭</button></header><MinutesGenerationPanel v-if="generationOpened&&owner&&value?.body" :meeting-id="meetingId" :auto-start="regenerationAuto" @started="generationStarted" @changed="reload();emit('changed')"/></dialog>
 <p v-if="editor.loading.value&&!value" role="status">正在读取已保存纪要…</p>
 <template v-if="value"><p v-if="value.observation.readOnlyReason&&stage!=='published'" class="small muted">当前纪要只读：{{value.observation.readOnlyReason==='PUBLISHED'?'会议已发布':'已进入最终确认或发布流程'}}</p><article v-if="value.body" v-show="view==='body'" class="minutes-body am-body-card"><div v-if="stage==='minutes'" class="am-document-toolbar"><div class="flex"><MinutesTemplateToolbar v-if="owner" :meeting-id="meetingId" :current="value" :locked="!!locked" @select="id=>command('MINUTES_TEMPLATE',{templateRevisionId:id})" @create="futurePanels?.open('template')" @denied="denied"/><button v-if="owner" class="btn primary" :disabled="!!locked" @click="openGeneration">重新生成</button></div><div class="am-document-actions" v-if="owner"><button class="btn sm ghost" :disabled="!!editor.draft.value?.dirty.value" @click="copyBody">复制全文</button><button class="btn sm" aria-label="下载 Markdown" :disabled="!!editor.draft.value?.dirty.value" @click="downloadBody">⇩ 下载</button><button class="btn sm" aria-label="编辑正文" :disabled="!!locked" @click="edit({kind:'BODY',id:value.body.id})">✎ 编辑</button></div></div><p v-if="copyMessage" class="small muted" role="status">{{copyMessage}}</p><template v-if="bodyEditing&&stage==='minutes'"><MinutesTextEditor :editor="editor" :compact="true" @saved="emit('changed')"/><button class="btn sm" :disabled="editor.busy.value||!editor.intent.canAutosave.value" @click="finishBodyEdit">完成编辑</button></template><template v-else><h3>{{value.body.title}}</h3><pre>{{value.body.body}}</pre><button v-if="owner&&stage!=='published'" class="btn sm ghost" :disabled="editor.busy.value||editor.loading.value" @click="inspect({kind:'BODY',id:value.body.id})">查看正文来源与审阅</button><button v-if="owner&&stage==='published'" class="btn sm" @click="downloadBody">下载 Markdown</button></template></article><p v-else-if="view==='body'">尚无已保存正文。生成完成后可在候选中检查结果。</p>
 <p v-if="view==='elements'&&!value.setId">尚无已保存核心要素。确认转写并生成后，可在此核对来源和行动项。</p>
 <div v-show="view==='elements'" class="core-layout am-layout"><nav class="core-navigation am-toc" aria-label="核心要素分类"><button v-for="(items,category) in displayGroups" :key="category" class="core-category toc-item" :class="{selected:selectedCategory===category}" :aria-current="selectedCategory===category?'location':undefined" @click="categoryView(category)">{{categoryLabels[category]??category}}</button><button class="core-category toc-item" :class="{selected:selectedCategory==='SENSITIVE'}" @click="categoryView('SENSITIVE')">敏感信息</button></nav><div class="core-content am-sections"> <div v-for="(items,category) in displayGroups" :key="category" :id="'minutes-category-'+category" class="minutes-elements"><template v-if="true"><div class="between"><h3>{{categoryLabels[category]??category}}</h3><button v-if="owner&&stage==='minutes'" class="btn sm ghost" aria-label="局部重新生成" @click="futurePanels?.open('regenerate',categoryLabels[category])">♧ 局部重新生成</button></div><p v-if="!items.length" class="empty small">暂未总结出相关内容，请核对会议文件与背景材料。</p><article v-for="item in items.slice((pages[category]??0)*20,((pages[category]??0)+1)*20)" :key="item.id" :data-element-id="item.id"><p class="text">{{item.body}}</p><p v-if="item.action">负责人：{{item.action.owner_display??'未指定'}} · 日期：{{item.action.due_on??'未指定'}}</p><button v-if="owner" class="am-source-tag" :disabled="editor.busy.value||editor.loading.value" @click="inspect({kind:'ELEMENT',id:item.id})">♧ 已确认会议转写 · 来源与审阅</button><button v-if="owner&&stage!=='published'" class="btn sm ghost element-edit" :disabled="locked" @click="edit({kind:'ELEMENT',id:item.id})" aria-label="编辑要素">✎</button></article><button v-if="(pages[category]??0)>0" class="btn" @click="pages[category]=(pages[category]??0)-1">上一页</button><button v-if="((pages[category]??0)+1)*20<items.length" class="btn" @click="pages[category]=(pages[category]??0)+1">下一页</button></template></div>
 <MinutesSensitive ref="sensitiveRef" :meeting-id="meetingId" :current="value" :owner="owner" :locked="!!locked||actions.busy.value" :save-selection="fields=>command('MINUTES_EXCLUSIONS',fields)" @source="inspect" @denied="denied"/></div></div>
 <dialog ref="inspectDialog" class="workspace-dialog source-dialog" aria-label="来源与审阅"><header class="between"><h3>来源与审阅</h3><button class="btn sm" @click="inspectDialog?.close()">关闭</button></header><section v-if="selected&&selectedContent" v-show="view==='body'||view==='elements'" class="inspection" role="region" aria-label="所选内容的来源与审阅" tabindex="-1"><h3>所选内容的来源</h3><textarea readonly rows="6" :value="selectedContent.body" @select="range"/><ul><li v-for="e in value.evidence.filter(e=>selected?.kind==='BODY'?e.minutes_revision_id===selected.id:e.element_id===selected?.id)" :key="e.id">{{e.support_state}} <button class="btn" @click="read(s=>app.minutesInspection.source(meetingId,e.locator_id,selected!,s),v=>source=v)">查看原始段落</button></li></ul><article v-if="source"><pre>{{source.text}}</pre><p>来源版本 {{source.sourceVersion}} · {{source.marks.join('、')}}</p><a :href="source.originalBytes.route" target="_blank" rel="noopener">读取原始文件</a></article>
  <div v-if="owner"><label>来源支持结论<select v-model="reviewOutcome"><option value="SUPPORTED">有充分支持</option><option value="PARTIAL">部分支持</option><option value="UNSUPPORTED">无支持</option></select></label><button class="btn" :disabled="locked" @click="review(false)">提交全文审阅</button><button class="btn" :disabled="locked||!reviewSelection" @click="review(true)">审阅所选文字</button><p>局部审阅不会替代全文审阅。</p><button class="btn" @click="loadReviews()">读取审阅记录</button><ul v-if="reviewHistory"><li v-for="r in reviewHistory.items" :key="r.id">{{r.review_kind}} · {{r.outcome}} · {{r.reviewed_by}} · {{r.reviewed_at}}</li></ul><button v-if="reviewHistory?.hasMore" class="btn" @click="loadReviews(reviewHistory.nextBeforeReviewNoToken)">下一页审阅</button><button v-if="selected.kind==='ELEMENT'" class="btn" :disabled="locked" @click="convertQuestion">转换为待确认问题</button>
   <template v-if="'action' in selectedContent&&selectedContent.action"><h4>行动项已接受字段</h4><p>负责人和日期均以当前已保存字段为准，修改后需要重新审阅确认。</p><ActionOwnerSelection :meeting-id="meetingId" :element-id="selected!.id" :revision-token="value.observation.revisionToken" :enabled="!locked&&!actions.busy.value" :has-identity="!!selectedContent.action.owner_enterprise_id" @save="assignOwner" @denied="denied"/><button class="btn" :disabled="locked" @click="edit({kind:'ACTION',id:selected!.id})">编辑负责人和截止日期</button><button class="btn" :disabled="locked" @click="command('MINUTES_REVIEW',{target:{kind:'ELEMENT',id:selected!.id},reviewKind:'ACTION_FIELDS',scope:null,outcome:'CONFIRMED'})">确认已保存的负责人和日期</button></template>
  </div>
 </section></dialog>
 </template>
 <template v-if="owner&&app.minutesScopeReady.value&&!accessDenied"><dialog ref="editDialog" class="workspace-dialog" aria-label="编辑纪要内容"><header class="between"><h3>编辑纪要内容</h3><button class="btn sm" @click="editDialog?.close()">关闭</button></header><MinutesTextEditor :editor="editor" @saved="emit('changed')"/></dialog><dialog ref="toolsDialog" class="workspace-dialog" aria-label="候选与版本"><header class="between"><h3>候选与版本</h3><button class="btn sm" @click="toolsDialog?.close()">关闭</button></header><section class="minutes-candidates"><h3>生成候选</h3><select v-model="candidateState" @change="candidates=null;candidate=null"><option value="PENDING">待决定</option><option value="STALE">已过期</option><option value="ADOPTED">已采用</option><option value="REJECTED">已拒绝</option></select><button class="btn" :disabled="busy" @click="loadCandidates()">读取候选</button><ul v-if="candidates"><li v-for="item in candidates.items" :key="item.candidateId">{{item.state}} · {{item.createdAt}} <button class="btn" @click="inspectCandidate(item.candidateId)">检查候选</button></li></ul><button v-if="candidates?.nextCursor" class="btn" @click="loadCandidates(candidates.nextCursor)">下一页</button><dialog ref="candidateDialog" class="candidate-dialog" aria-labelledby="candidate-dialog-title" @click="candidateBackdrop"><header><h3 id="candidate-dialog-title">核对纪要候选</h3><button class="btn" aria-label="关闭候选对比" @click="candidateDialog?.close()">关闭</button></header><div class="candidate-columns"><section><h4>当前已保存纪要</h4><template v-if="value?.body"><h4>{{value.body.title}}</h4><pre>{{value.body.body}}</pre></template><p v-else>尚无已保存纪要。</p><p class="muted">未保存的本地编辑继续保留；请先保存或处理草稿，再决定采用。</p></section><article v-if="candidate"><h4>新生成候选</h4><p>{{candidate.candidate.state}} · {{candidate.eligibility.reasons.join('、')}}</p><div v-for="body in candidate.graph.minutes_revision.filter(body=>body.id===candidate!.candidate.minutesRevisionId)" :key="body.id"><h4>{{body.title}}</h4><pre>{{body.body}}</pre></div><div v-for="element in selectedCandidateElements.slice(candidatePage*20,(candidatePage+1)*20)" :key="element.id"><h4>{{categoryLabels[element.category]??element.category}} · {{element.support_state}}</h4><p class="text">{{element.body}}</p><p v-for="suggestion in candidate.graph.action_suggestion.filter(x=>x.element_id===element.id)" :key="suggestion.element_id">建议负责人：{{suggestion.owner_mention??'未提供'}} · 建议日期：{{suggestion.due_on??'未提供'}}（尚未接受）</p></div><button v-if="candidatePage>0" class="btn" @click="candidatePage--">上一页候选要素</button><button v-if="(candidatePage+1)*20<selectedCandidateElements.length" class="btn" @click="candidatePage++">下一页候选要素</button><p>采用后将建立新的已保存正文和要素集合；人工标题由服务器按当前规则保护。</p></article></div><footer v-if="candidate"><button class="btn" :disabled="locked||workspaceDirty||actions.busy.value||!['PENDING','STALE'].includes(candidate.candidate.state)" @click="keepCurrentCandidate">保留当前稿</button><button class="btn primary" :disabled="locked||workspaceDirty||actions.busy.value||!candidate.eligibility.canAdopt" @click="command('MINUTES_ADOPT',{inputId:candidate!.candidate.inputId,inputFingerprint:candidate!.candidate.inputFingerprint},candidate!.candidate.candidateId)">采用此候选</button><button class="btn" :disabled="locked||workspaceDirty||actions.busy.value||candidate.candidate.state!=='PENDING'" @click="command('MINUTES_REJECT',{},candidate!.candidate.candidateId)">拒绝此候选</button><button class="btn" :disabled="locked||workspaceDirty||actions.busy.value||!['PENDING','STALE'].includes(candidate.candidate.state)" @click="command('MINUTES_DISPOSE',{},candidate!.candidate.candidateId)">处置此候选</button></footer></dialog></section>
 <MinutesSettings v-if="value" :meeting-id="meetingId" :current="value" :locked="!!locked" :editable="actionIntent.canEdit.value" @begin="actionIntent.request(value.observation.revisionToken).catch(e=>error=e.message)" @save="(op,fields)=>command(op,fields)" @denied="denied"/>
 <MinutesHistory :meeting-id="meetingId" :enabled="true" :locked="!!locked" @denied="denied" @restore="(kind,id)=>command(kind==='BODY'?'MINUTES_BODY_RESTORE':'MINUTES_SET_RESTORE',kind==='BODY'?{sourceRevisionId:id}:{sourceSetId:id})"/>
 </dialog>
 <p v-if="actions.error.value" role="alert">{{actions.error.value instanceof Error?actions.error.value.message:'原操作结果待确认。'}}</p><button v-if="['PREPARED','UNCERTAIN','ACKNOWLEDGED'].includes(actions.command.state.value)&&actions.command.snapshot.value" class="btn" :disabled="actions.busy.value" @click="actions.retry">查回原决定结果</button><button v-if="['CONFLICT','REJECTED'].includes(actions.command.state.value)" class="btn" @click="actions.reset();reload()">重新读取后再决定</button>
 </template><PublicationPanel @info-saved="emit('infoSaved')" :stage="stage" @navigate="stage=>emit('navigate',stage)" v-show="view==='publication'||stage==='published'" :target-labels="reviewLabels" :meeting-info="meetingInfo" :saved-minutes="value??undefined" @edit-info="emit('editInfo')" @published="emit('published')" v-if="!accessDenied" :meeting-id="meetingId" :owner="owner" :locked="!!locked||actions.busy.value||['PREPARED','SENDING','UNCERTAIN'].includes(actions.command.state.value)" @changed="reload();emit('changed')" @denied="denied"/><footer v-if="stage==='minutes'&&value?.body&&!value.observation.readOnlyReason" class="acf-dock"><div class="acf-inner"><span class="acf-hint">{{editor.draft.value?.dirty.value?'有未保存的纪要修改，请先保存。':''}}</span><button class="btn primary" :disabled="!!locked||actions.busy.value" @click="emit('navigate','confirm')">进入会议确认 ›</button></div></footer></section><FuturePanels ref="futurePanels"/><dialog ref="dirtyDialog" class="notice-dialog" aria-labelledby="dirty-minutes-title" @cancel.prevent="decideLeave('stay')"><h3 id="dirty-minutes-title">有尚未保存的修改</h3><p class="mt16">请选择如何处理当前纪要草稿。</p><div class="flex mt16"><button class="btn" @click="decideLeave('stay')">继续编辑</button><button class="btn" :disabled="editor.busy.value" @click="decideLeave('discard')">放弃修改</button><button class="btn primary" :disabled="editor.busy.value||actions.busy.value||(editor.draft.value?.dirty.value&&!editor.intent.canAutosave.value)" @click="decideLeave('save')">保存并继续</button></div></dialog></template>
